configuration_files.system/createPatchDict:
FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      createPatchDict;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

pointSync false;

// Patches to create.
patches
(
    {
        // Name of new patch
        name oversetPatch;

        // Dictionary to construct new patch from
        patchInfo
        {
            type overset;
        }

        // How to construct: either from 'patches' or 'set'
        constructFrom patches;

        // If constructFrom = patches : names of patches. Wildcards allowed.
        patches (otherSide);

        // If constructFrom = set : name of faceSet
        set f0;
    }

    {
        // Name of new patch
        name walls;

        // Dictionary to construct new patch from
        patchInfo
        {
            type wall;
        }

        // How to construct: either from 'patches' or 'set'
        constructFrom patches;

        // If constructFrom = patches : names of patches. Wildcards allowed.
        patches (originalPatch);

        // If constructFrom = set : name of faceSet
        set f0;
    }

    {
        // Name of new patch
        name frontAndBack;

        // Dictionary to construct new patch from
        patchInfo
        {
            type empty;
        }

        // How to construct: either from 'patches' or 'set'
        constructFrom patches;

        // If constructFrom = patches : names of patches. Wildcards allowed.
        patches (sides);

        // If constructFrom = set : name of faceSet
        set f0;
    }
);


