    {
        name    box;
        type    cellSet;
        action  new;
        source  cellToCell;
        set     c1;
    }

    {
        name    box;
        type    cellSet;
        action  subset;
        source  boxToCell;
        box     (0.4 0.4 -100)(0.6 0.6 100);
    }

    {
        name    box;
        type    cellSet;
        action  invert;
    }
