        relTol          0;
    }

    p_rgh
    {
        solver           GAMG;
        tolerance        1e-7;
        relTol           0.01;
        preconditioner  DIC;
        smoother         GaussSeidel;
        agglomerator     assembledFaceAreaPair;
        maxIter         100;
        cacheAgglomeration  false;

    }

    p_rghFinal
    {
        $p_rgh;
        tolerance        1e-7;
        relTol           0;
    }

    h
    {
        solver           GAMG;
        tolerance        1e-7;
        relTol           0.01;
        preconditioner  DIC;
        smoother         GaussSeidel;
        agglomerator     assembledFaceAreaPair;
        cacheAgglomeration  false;
    }

    hFinal
    {
        $h;
        tolerance        1e-7;
        relTol           0;
    }

    "(U|k|epsilon|R)"
    {
        solver           PBiCGStab;
        preconditioner   DILU;
        tolerance        1e-7;
        relTol           0.1;
    }

    "(U|k|epsilon|R)Final"
    {
        $U;
        tolerance        1e-7;
        relTol           0;
    }
}

PIMPLE
{
    momentumPredictor   no;
    nCorrectors         3;
    nNonOrthogonalCorrectors 0;
    pRefPoint        (0.09 0 0);
    pRefValue       1e5;
}

relaxationFactors
{
    equations
    {
        ".*"           1;
    }
}

