// Baffles to create.
baffles
{
    cyclicFaces
    {
        //- Select faces and orientation through a searchableSurface
        type        searchableSurface;
        surface     plate;
        origin      (0.061 -0.3 -0.3);
        span        (0.0 0.6 0.6);

        patches
        {
            master
            {
                //- Master side patch

                name            porous_half0;
                type            cyclic;
                neighbourPatch  porous_half1;

                //- Optional override of added patchfields. If not specified
                //  any added patchfields are of type calculated.
                patchFields
                {
                    p_rgh
                    {
                        type            cyclic;//porousBafflePressure;
                        patchType       cyclic;
                        D               1000;
                        I               500;
                        length          0.15;
                        uniformJump     true;
                        jump            uniform 0;
                        value           uniform 0;
                    }
                }
            }
            slave
            {
                //- Slave side patch

                name            porous_half1;
                type            cyclic;
                neighbourPatch  porous_half0;

                patchFields
                {
                    ${../../master/patchFields}
                }
            }
        }
    }
}


