        box     (-0.01001 -100 -0.01001)(0.01001 0.00999 0.01001);
    }
    {
        name    heater;
        type    cellZoneSet;
        action  new;
        source  setToCellZone;
        set     heaterCellSet;
    }

    // leftSolid
    {
        name    leftSolidCellSet;
        type    cellSet;
        action  new;
        source  boxToCell;
        box     (-100 0 -100)(-0.01001 0.00999 100);
    }
    {
        name    leftSolid;
        type    cellZoneSet;
        action  new;
        source  setToCellZone;
        set     leftSolidCellSet;
    }

    // rightSolid
    {
        name    rightSolidCellSet;
        type    cellSet;
        action  new;
        source  boxToCell;
        box     (0.01001 0 -100 )(100 0.00999 100);
    }
    {
        name    rightSolid;
        type    cellZoneSet;
        action  new;
        source  setToCellZone;
        set     rightSolidCellSet;
    }

    // topAir
    {
        name    topAirCellSet;
        type    cellSet;
        action  new;
        source  boxToCell;
        box     (-100 0.00999 -100 )(100 100 100);
    }
    {
        name    topAir;
        type    cellZoneSet;
        action  new;
        source  setToCellZone;
        set     topAirCellSet;
    }


    // bottomAir is all the other cells
    {
        name    bottomAirCellSet;
        type    cellSet;
        action  new;
        source  cellToCell;
        set     heaterCellSet;
    }
    {
        name    bottomAirCellSet;
        type    cellSet;
        action  add;
        source  cellToCell;
        set     leftSolidCellSet;
    }
    {
        name    bottomAirCellSet;
        type    cellSet;
        action  add;
        source  cellToCell;
        set     rightSolidCellSet;
    }
    {
        name    bottomAirCellSet;
        type    cellSet;
        action  add;
        source  cellToCell;
        set     topAirCellSet;
    }
    {
        name    bottomAirCellSet;
        type    cellSet;
        action  invert;
    }
    {
        name    bottomAir;
        type    cellZoneSet;
        action  new;
        source  setToCellZone;
        set     bottomAirCellSet;
    }
);


