        T               cell;
        Cp              cell;
        kappa           cell;
        p               cell;
    }

    integrationSchemes
    {
        U               Euler;
        T               analytical;
    }
}

constantProperties
{
    rho0            1000;
    T0              310;
    Cp0             4100;

    constantVolume  false;
}

subModels
{
    particleForces
    {
        sphereDrag;
        gravity;
    }

    injectionModels
    {
// using droplets distribution from 2009 Chao paper
// https://www.ncbi.nlm.nih.gov/pmc/articles/PMC7126899/

// to allow an easier check of the number of particles hitting a patch
// according to their size, we will reduce the number of model* parcel and
// comment some of them, so to get a shorter list, easier to verify.
        model3 // diameter  3 μm => 0.000003m
        {
            type            patchInjection;
            parcelBasisType fixed;
            patch           mouth;
            U0              (4.0 0.0 0.0);
            nParticle       1; //  1 particles = one parcel
            parcelsPerSecond 2; // taken from 3rd column of table https://www.ncbi.nlm.nih.gov/pmc/articles/PMC7126899/table/tbl1/
            sizeDistribution
            {
                type uniform;
                uniformDistribution
                {
                    minValue        0.000003;
                    maxValue        0.000003;
                }
            }
            flowRateProfile constant 1;
            massTotal       0;
            SOI 0.0;
            duration 120.0;
        }

        model6 // diameter  6 μm => 0.000006m
        {
            type            patchInjection;
            parcelBasisType fixed;
            patch           mouth;
            U0              (4.0 0.0 0.0);
            nParticle       1; //  1 particles = one parcel
            parcelsPerSecond 27;
            sizeDistribution
            {
                type uniform;
                uniformDistribution
                {
                    minValue        0.000006;
                    maxValue        0.000006;
                }
            }
            flowRateProfile constant 1;
            massTotal       0;
            SOI 0.0;
            duration 120.0;
        }

        model12 // diameter  12 μm => 0.000012m
        {
            type            patchInjection;
            parcelBasisType fixed;
            patch           mouth;
            U0              (4.0 0.0 0.0);
            nParticle       1; //  1 particles = one parcel
            parcelsPerSecond 9;
            sizeDistribution
            {
                type uniform;
                uniformDistribution
                {
                    minValue        0.000012;
                    maxValue        0.000012;
                }
            }
            flowRateProfile constant 1;
            massTotal       0;
            SOI 0.0;
            duration 120.0;
        }

        model20 // diameter  20 μm => 0.000020m
        {
            type            patchInjection;
            parcelBasisType fixed;
