maxCo           0.4;

maxAlphaCo      0.4;

maxDeltaT       0.01;

functions
{
    line
    {
        type            sets;
        libs            (sampling);
        enabled         true;
        writeControl    onEnd;

        interpolationScheme cellPoint;
        setFormat       raw;
        fixedLocations  false;

        fields          (alpha.water);

        sets
        {
            s1
            {
                type            uniform;
                axis            distance;
                start           ( 0.865 0.275 0.0 );
                end             ( 0.865 0.275 0.5 );
                nPoints         101;
