            s2
            {
                type            uniform;
                axis            distance;
                start           ( 1.065 0.275 0.0 );
                end             ( 1.065 0.275 0.5 );
                nPoints         101;
            }

            s3
            {
                type            uniform;
                axis            distance;
                start           ( 4.1 0.275 0.0 );
                end             ( 4.1 0.275 0.5 );
                nPoints         101;
            }

            s4
            {
                type            uniform;
                axis            distance;
                start           ( 4.645 0.275 0.0 );
                end             ( 4.645 0.275 0.5 );
                nPoints         101;
            }

            s5
            {
                type            uniform;
                axis            distance;
                start           ( 5.2 0.275 0.0 );
                end             ( 5.2 0.275 0.5 );
                nPoints         101;
            }

            s6
            {
                type            uniform;
                axis            distance;
                start           ( 5.85 0.275 0.0 );
                end             ( 5.85 0.275 0.5 );
                nPoints         101;
            }

            s7
            {
                type            uniform;
                axis            distance;
                start           ( 6.15 0.275 0.0 );
                end             ( 6.15 0.275 0.5 );
                nPoints         101;
            }
        }
    }
}


