                            (mercury and liquid) 1
                            (mercury and oil)    1
                            (liquid and oil)     1
                        );

        nAlphaCorr      2;
        nAlphaSubCycles 3;

        // Compressiion factor for species in each alpha phase
        // NOTE: It should be similar to cAlpha
        cYi             1;
    }

    "U.*"
    {
        solver          smoothSolver;
        smoother        symGaussSeidel;
        tolerance       1e-7;
        relTol          0;
    };

    "(T.*)"
    {
        solver          PBiCGStab;
        preconditioner  DILU;
        tolerance       1e-08;
        relTol          0.0;
        residualAlpha   1e-7;
    }

