    {
        solver              PBiCGStab;
        preconditioner      FDIC;
        tolerance           1e-9;
        relTol              0.01;
    };

    p_rghFinal
    {
        $p_rgh;
        relTol          0;
    };

    "pcorr.*"
    {
        solver          PCG;
        preconditioner  DIC;
        tolerance       1e-5;
        relTol          0;
    }
}

