    div(phiSt,b)    Gauss limitedLinear 1;

    div(phi,K)      Gauss limitedLinear 1;

    div(phi,ft_b_ha_hau_H2OPS_Y) Gauss multivariateSelection
    {
        ft          limitedLinear01 1;
