        ft          limitedLinear01 1;
        b           limitedLinear01 1;
        Xi          limitedLinear 1;
        Xp          limitedLinear 1;
        Ep          limitedLinear 1;
        h           limitedLinear 1;
        hu          limitedLinear 1;
        ha          limitedLinear 1;
        hau         limitedLinear 1;
