// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

SIMPLE
{
    nNonOrthogonalCorrectors 0;
}

solvers
{
    "(p|pa).*"
    {
        solver           PCG;
        preconditioner   DIC;
        tolerance        1e-9;
        relTol           0.01;
    };

    "(m|ma).*"
    {
        solver           PCG;
        preconditioner   DIC;
        tolerance        1e-9;
        relTol           0.01;
    };

    "(U.*|Ua.*|nuTilda.*|nuaTilda.*|yWall|da.*)"
    {
        solver           PBiCGStab;
        preconditioner   DILU;
        tolerance        1e-9;
        relTol           0.1;
    };
}

relaxationFactors
{
    fields
    {
       "p.*"            0.5;
       "pa.*"           0.5;
    }
    equations
    {
        "U.*"           0.7;
        "Ua.*"          0.7;
        "nuTilda.*"     0.7;
        "nuaTilda.*"    0.7;
        yWall           0.7;
        "da.*"          0.7;
    }
}


