configuration_files.system/fvSolution:
FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      fvSolution;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

SIMPLE          
{
    nNonOrthogonalCorrectors 0;
}

solvers
{
    "p|pa.*|bTilda"
    {
        solver          PCG;
        preconditioner  DIC;
        tolerance       1e-09;
        relTol          0.1;
    }

    "U.*|Ua.*|nuTilda.*|nuaTilda.*|yWall.*|da.*"
    {
        solver      PBiCGStab;
        preconditioner   DILU;
        tolerance   1e-9;
        relTol      0.1;
    };
}

relaxationFactors 
{
    fields
    {
        p               0.3;
       "pa.*"           0.7;
    }
    equations
    {
        U               0.7;
       "Ua.*"           0.3;
       "nuT.*"          0.3;
       "nua.*"          0.3;
        yWall           0.7;
       "da.*"           0.7;
    }
}

