{
    fields
    {
        p               0.3;
       "pa.*"           0.7;
    }
    equations
    {
        U               0.7;
       "Ua.*"           0.3;
       "nuT.*"          0.3;
       "nua.*"          0.3;
        yWall           0.7;
       "da.*"           0.7;
