    {
        p               0.3;
       "pa.*"           0.5;
    }
    equations
    {
        U               0.8;
       "Ua.*"           0.2;
       "nuT.*"          0.3;
       "nua.*"          0.2;
        yWall           0.7;
       "da.*"           0.7;
