{
    designVariables
    {
        type topO;
        sensitivityType topO;
        fixedZeroPorousZones   (IEntranceZone OEntranceZone OREntranceZone);
        regularisation
        {
            regularise     true;
            growFromWalls  true;
            meanRadiusMult 10;
            function       tanh;
            b              20;
        }
        betaMaxType    Darcy;
        DarcyCoeffs
        {
            inletPatches (inlet);
        }
        maxInitChange 0.2;
    }
    updateMethod
    {
        method nullSpace;
        strictMaxDVChange true;
    }
}


