                                {
                                    type      stepRamp;
                                    start     0;
                                    duration  20;
                                    interval  5;
                                }
                                value
                                {
                                    type constant;
                                    value constant 0.538;
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

optimisation
{
    designVariables
    {
        type levelSet;
        sensitivityType topO;
        fixedZeroPorousZones   (IEntranceSet OEntranceSet OREntranceSet);
        regularisation
        {
            regularise     true;
            meanRadiusMult 5;
            //radius 0.05;
        }
        interpolation
        {
            function    sigmoidalHeaviside;
            meanRadiusMult  1;
            //d           0.01;
        }
        initialisation
        { 
            method      meshWave;
        }
        betaMax    2500;
    }
    updateMethod
    {
        method MMA;
        eta 1;
    }
}

