                type                   incompressible;
                solver                 adjointSimple;
                // manage objectives
                //------------------
                objectives
                {
                    type  incompressible;
                    objectiveNames
                    {
                        losses
                        {
                            weight          1.; 
                            type            PtLosses;
                            patches         ("inlet.*" "outlet.*");
                            normalize       true;
                        }
                        uniformity
                        {
                            weight            0.; 
                            type              uniformityPatch;
                            patches           (outlet1 outlet2);
                        }
                        mass
                        {
                            weight            0.; 
                            type              flowRatePartition;
                            inletPatches      (inlet);
                            outletPatches     (outlet1 outlet2);
                            targetFractions   (0.5 0.5);
