    consistent          yes;
    residualControl
    {
        p               1e-5;
        U               1e-5;
        "(k|epsilon|omega|nuTilda|phit|f)" 1e-5;
    }
}

relaxationFactors
{
    equations
    {
        U               0.9;
        "(k|epsilon|omega|nuTilda|phit|f)" 0.7;
    }
}

cache
{
    grad(U);
}


