        dynamicContactAngleCoeffs
        {
            Ccf     0.4;
            Ttheta  constant 0;
            distribution
            {
                type            normal;
                normalDistribution
                {
                    minValue        $CON;
                    maxValue        $CON;
                    mu              $CON;
                    sigma           100;
